import React from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import Welcome from "./pages/Welcome";
import SignupForm from "./auth/SignupForm";
import LoginForm from "./auth/LoginForm";
import Dashboard from "./pages/Dashboard";
import UserDashboard from "./pages/UserDashboard";
// import AdminDashboard from "./pages/AdminDashboard";
import AdminHome from "./pages/AdminHome";
import AdminUsersPage from "./pages/AdminUsersPage";
import AdminReportsPage from "./pages/AdminReportsPage";
import AdminChallengesPage from "./pages/AdminChallengesPage";
import AdminGroupsPage from "./pages/AdminGroupsPage";
import VerifyEmail from "./auth/VerifyEmail";
import { isAuthenticated, isAdmin } from "./services/auth";
import ForgotPasswordPage from "./components/ForgotPasswordPage";
import ResetPasswordPage from "./components/ResetPasswordPage";
import Journal from './pages/Journal';
import ThemedLayout from "./layouts/ThemedLayout";
import SettingsPage from "./pages/SettingsPage";
import HabitsPage from "./pages/HabitsPage";
import GoalsPage from "./pages/GoalsPage";
import { HabitsProvider } from './contexts/HabitsContext';
import { GoalsProvider } from './contexts/GoalsContext';
import { NotificationProvider } from './contexts/NotificationContext';
import { Toaster } from 'react-hot-toast';
import CommunityPage from "./pages/CommunityPage";
import PostDetailPage from "./pages/PostDetailPage";
import BrowseChallengesPage from "./pages/BrowseChallengesPage";
import BrowseGroupsPage from "./pages/BrowseGroupsPage";
import GroupDetailsPage from "./pages/GroupDetailsPage";
import MemoryCapsule from './pages/MemoryCapsule';
import AnalyticsPage from "./pages/AnalyticsPage";
import GroupModeratorDashboard from "./pages/GroupModeratorDashboard";
import GroupModeratorMembers from "./pages/GroupModeratorMembers";
import GroupModeratorReports from "./pages/GroupModeratorReports";
import GroupModeratorRequests from "./pages/GroupModeratorRequests";
import ChallengeDetailPage from "./pages/ChallengeDetailPage";
import GroupSessionsPage from "./pages/GroupSessionsPage";
import GroupChatPage from "./pages/GroupChatPage";
import AdminSettings from "./pages/AdminSettings";
import { ThemeProvider } from "./contexts/ThemeContext";

// import { useEffect } from 'react';
// import { initializeSocket, disconnectSocket } from './services/socketService';
// import { isAuthenticated } from './services/auth';

function App() {
    const ProtectedRoute = ({ children }) => {
        return isAuthenticated() ? children : <Navigate to="/login" />;
    };

    const AdminRoute = ({ children }) => {
        if (!isAuthenticated()) return <Navigate to="/login" />;
        if (!isAdmin()) return <Navigate to="/user/dashboard" />;
        return children;
    };

    const queryClient = new QueryClient();

    return (
        <QueryClientProvider client={queryClient}>
            <Router>
                <Toaster position="top-center" />
                {/* ← WRAP EVERYTHING IN NotificationProvider */}
                <NotificationProvider>
                    <HabitsProvider>
                        <GoalsProvider>
                            <div className="App">
                                <Routes>
                                    {/* PUBLIC ROUTES - NO DARK MODE */}
                                    <Route path="/" element={<Welcome />} />
                                    <Route path="/signup" element={<SignupForm />} />
                                    <Route path="/login" element={<LoginForm />} />
                                    <Route path="/verify-email/:code" element={<VerifyEmail />} />
                                    <Route path="/forgot-password" element={<ForgotPasswordPage />} />
                                    <Route path="/reset-password/:token" element={<ResetPasswordPage />} />

                                    {/* REDIRECT DASHBOARD */}
                                    <Route
                                        path="/dashboard"
                                        element={
                                            <ProtectedRoute>
                                                <Dashboard />
                                            </ProtectedRoute>
                                        }
                                    />

                                    {/* PROTECTED ROUTES WITH DARK MODE */}
                                    <Route
                                        path="/user/dashboard"
                                        element={
                                            <ProtectedRoute>
                                                <ThemedLayout>
                                                    <UserDashboard />
                                                </ThemedLayout>
                                            </ProtectedRoute>
                                        }
                                    />

                                    <Route
                                        path="/journal"
                                        element={
                                            <ProtectedRoute>
                                                <ThemedLayout>
                                                    <Journal />
                                                </ThemedLayout>
                                            </ProtectedRoute>
                                        }
                                    />

                                    <Route
                                        path="/settings"
                                        element={
                                            <ProtectedRoute>
                                                <ThemedLayout>
                                                    <SettingsPage />
                                                </ThemedLayout>
                                            </ProtectedRoute>
                                        }
                                    />

                                    <Route
                                        path="/admin/dashboard"
                                        element={
                                            <AdminRoute>
                                                <ThemeProvider>
                                                    <AdminHome />
                                                </ThemeProvider>
                                            </AdminRoute>
                                        }
                                    />
                                    <Route
                                        path="/admin/users"
                                        element={
                                            <AdminRoute>
                                                <ThemeProvider>
                                                    <AdminUsersPage />
                                                </ThemeProvider>
                                            </AdminRoute>
                                        }
                                    />
                                    <Route
                                        path="/admin/reports"
                                        element={
                                            <AdminRoute>
                                                <ThemeProvider>
                                                    <AdminReportsPage />
                                                </ThemeProvider>
                                            </AdminRoute>
                                        }
                                    />
                                    <Route
                                        path="/admin/challenges"
                                        element={
                                            <AdminRoute>
                                                <ThemeProvider>
                                                    <AdminChallengesPage />
                                                </ThemeProvider>
                                            </AdminRoute>
                                        }
                                    />
                                    <Route
                                        path="/admin/groups"
                                        element={
                                            <AdminRoute>
                                                <ThemeProvider>
                                                    <AdminGroupsPage />
                                                </ThemeProvider>
                                            </AdminRoute>
                                        }
                                    />

                                    <Route
                                        path="/tasks"
                                        element={
                                            <ProtectedRoute>
                                                <ThemedLayout>
                                                    <HabitsPage />
                                                </ThemedLayout>
                                            </ProtectedRoute>
                                        }
                                    />

                                    <Route
                                        path="/goals"
                                        element={
                                            <ProtectedRoute>
                                                <ThemedLayout>
                                                    <GoalsPage />
                                                </ThemedLayout>
                                            </ProtectedRoute>
                                        }
                                    />
                                    <Route
                                        path="/capsules"
                                        element={
                                            <ProtectedRoute>
                                                <ThemedLayout>
                                                    <MemoryCapsule />
                                                </ThemedLayout>
                                            </ProtectedRoute>
                                        }
                                    />
                                    <Route
                                        path="/community"
                                        element={
                                            <ProtectedRoute>
                                                <ThemedLayout>
                                                    <CommunityPage />
                                                </ThemedLayout>
                                            </ProtectedRoute>
                                        }
                                    />

                                    <Route
                                        path="/community/challenges/browse"
                                        element={
                                            <ProtectedRoute>
                                                <BrowseChallengesPage />
                                            </ProtectedRoute>
                                        }
                                    />

                                    <Route
                                        path="/community/groups/browse"
                                        element={
                                            <ProtectedRoute>
                                                <BrowseGroupsPage />
                                            </ProtectedRoute>
                                        }
                                    />
                                    <Route path="/groups/:groupId/moderator/sessions" element={<GroupSessionsPage />} />

                                    <Route
                                        path="/analytics"
                                        element={
                                            <ProtectedRoute>
                                                <ThemedLayout>
                                                    <AnalyticsPage />
                                                </ThemedLayout>
                                            </ProtectedRoute>
                                        }
                                    />
                                    <Route path="/community" element={<CommunityPage />} />
                                    <Route path="/community/post/:postId" element={<PostDetailPage />} />
                                    <Route path="/challenges/browse" element={<BrowseChallengesPage />} />
                                    <Route path="/challenges/:id" element={<ChallengeDetailPage />} />

                                    <Route
                                        path="/community/group/:groupId"
                                        element={
                                            <ProtectedRoute>
                                                <ThemedLayout>
                                                    <GroupDetailsPage />
                                                </ThemedLayout>
                                            </ProtectedRoute>
                                        }
                                    />
                                    <Route
                                        path="/community/group/:groupId/chat/:connectionId"
                                        element={
                                            <ProtectedRoute>
                                                <ThemedLayout>
                                                    <GroupChatPage />
                                                </ThemedLayout>
                                            </ProtectedRoute>
                                        }
                                    />
                                    <Route
                                        path="/admin/groups/:groupId"
                                        element={
                                            <AdminRoute>
                                                <ThemeProvider>
                                                    <AdminGroupsPage />
                                                </ThemeProvider>

                                            </AdminRoute>
                                        }
                                    />
                                    <Route
                                        path="/admin/groups/:groupId/moderator/dashboard"
                                        element={
                                            <ProtectedRoute>
                                                <ThemeProvider>
                                                    <GroupModeratorDashboard />
                                                </ThemeProvider>

                                            </ProtectedRoute>
                                        }
                                    />
                                    <Route
                                        path="/admin/groups/:groupId/moderator/members"
                                        element={
                                            <ProtectedRoute>
                                                <ThemeProvider>
                                                    <GroupModeratorMembers />
                                                </ThemeProvider>
                                            </ProtectedRoute>
                                        }
                                    />
                                    <Route
                                        path="/admin/groups/:groupId/moderator/reports"
                                        element={
                                            <ProtectedRoute>
                                                <ThemeProvider>
                                                    <GroupModeratorReports />
                                                </ThemeProvider>


                                            </ProtectedRoute>
                                        }
                                    />
                                    <Route
                                        path="/admin/groups/:groupId/moderator/requests"
                                        element={
                                            <ProtectedRoute>
                                                <ThemeProvider>

                                                    <GroupModeratorRequests />
                                                </ThemeProvider>
                                            </ProtectedRoute>
                                        }
                                    />
                                    <Route
                                        path="/admin/settings"
                                        element={
                                            <AdminRoute>
                                                <ThemeProvider>

                                                    <AdminSettings />
                                                </ThemeProvider>
                                            </AdminRoute>
                                        }
                                    />
                                </Routes>
                            </div>
                        </GoalsProvider>
                    </HabitsProvider>
                </NotificationProvider>
            </Router>
        </QueryClientProvider>
    );
}

export default App;